const STORE_KEY = 'la-intencion-demo-v2';
// Sin dominio real (abierto como archivo), el QR usa una dirección de ejemplo
if (location.protocol === 'file:') window.CAFE_SITE_URL = 'https://cafe-la-intencion.example';
const SAMPLE_IMAGES = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const SESSION_KEY = 'la-intencion-demo-admin';
const memory = {};

const store = {
  get(key, area = 'local') {
    try {
      return window[area + 'Storage'].getItem(key);
    } catch {
      return memory[area + key] || null;
    }
  },
  set(key, value, area = 'local') {
    try {
      window[area + 'Storage'].setItem(key, value);
    } catch {
      memory[area + key] = value;
    }
  },
  del(key, area = 'local') {
    try {
      window[area + 'Storage'].removeItem(key);
    } catch {
      delete memory[area + key];
    }
  },
};

const RULES = { lastSeatingBeforeCloseMinutes: 60 };

function seed() {
  const hours = {};
  for (let d = 1; d <= 5; d++) hours[d] = ['07:00', '19:00'];
  hours[6] = ['08:00', '20:00'];
  hours[0] = ['08:00', '20:00'];
  const settings = {
    businessName: 'Café La Intención',
    timezone: 'Europe/Madrid',
    phone: '+1 555 010 0199',
    email: 'hola@laintencion.example',
    address: 'Calle de la Calma 12, Ciudad de ejemplo',
    instagram: '',
    whatsapp: '15550100199',
    countryCode: '1',
    notifyEmail: '',
    autoConfirm: true,
    totalSeats: 30,
    maxPartySize: 8,
    slotMinutes: 30,
    durationMinutes: 90,
    maxDaysAhead: 60,
    minLeadMinutes: 60,
    hours,
  };
  const today = time.nowInTimezone(settings.timezone).date;
  const day = (n) => time.addDays(today, n);
  const iso = (n, h) => new Date(Date.now() - n * 36e5 - h * 6e4).toISOString();
  const menu = [
    ['Pour Over', 'Café de origen filtrado a mano. Notas florales y acidez suave.', 'Filtrado', '$4.50'],
    ['Espresso', 'Intenso y aterciopelado, con crema densa y final largo.', 'Clásico', '$3.00'],
    ['Flat White', 'Doble espresso con leche texturizada, cremoso y equilibrado.', 'Con leche', '$4.00'],
    ['Cold Brew', 'Infusión en frío durante 18 horas. Suave, dulce y refrescante.', 'Frío', '$4.50'],
    ['Cortado', 'Espresso cortado con un toque de leche caliente.', 'Corto', '$3.50'],
    ['Té de temporada', 'Hojas sueltas, infusión lenta. Pregunta por la selección del día.', 'Infusión', '$3.50'],
  ].map(([name, description, tag, price], i) => ({ id: 'm' + (i + 1), name, description, tag, price, position: i + 1, isVisible: true, image: SAMPLE_IMAGES[i] || null }));
  const r = (id, name, email, phone, partySize, date, t, notes, status) => ({
    id, name, email, phone, partySize, date, time: t, notes, status, createdAt: iso(3, 0), updatedAt: iso(3, 0),
  });
  const reservations = [
    r('r1', 'Lucía Fernández', 'lucia@correo.example', '+1 555 010 0111', 2, day(0), '10:00', 'Mesa junto a la ventana, por favor.', 'confirmed'),
    r('r2', 'Marco Silva', '', '+1 555 010 0122', 4, day(0), '12:30', 'Cumpleaños de mi madre.', 'pending'),
    r('r3', 'Ana Torres', 'ana@correo.example', '+1 555 010 0133', 3, day(1), '09:00', '', 'confirmed'),
    r('r4', 'Daniel Ortega', '', '+1 555 010 0144', 6, day(2), '16:00', 'Somos 6, uno con silla de ruedas.', 'pending'),
    r('r5', 'Sofía Mena', 'sofia@correo.example', '+1 555 010 0155', 2, day(-1), '11:00', '', 'completed'),
    r('r6', 'Pedro Rojas', 'pedro@correo.example', '+1 555 010 0166', 2, day(-2), '08:30', '', 'no_show'),
  ];
  const messages = [
    { id: 'c1', name: 'Valeria Cruz', email: 'valeria@correo.example', subject: 'Eventos privados', message: 'Hola, ¿organizan eventos privados para unas 20 personas? Gracias.', isRead: false, createdAt: iso(2, 0) },
    { id: 'c2', name: 'Andrés Paz', email: 'andres@correo.example', subject: '', message: 'Gracias por la atención de ayer, el pour over estaba excelente.', isRead: true, createdAt: iso(30, 0) },
    { id: 'c3', name: 'Irene Vega', email: 'irene@correo.example', subject: 'Granos para llevar', message: '¿Venden café en grano para llevar a casa?', isRead: false, createdAt: iso(50, 0) },
  ];
  const activity = [
    { id: 1, admin: 'demo@demo.example', action: 'login', detail: 'Inició sesión', createdAt: iso(26, 0) },
    { id: 2, admin: 'demo@demo.example', action: 'settings_updated', detail: 'Cambió: horarios, whatsapp', createdAt: iso(25, 0) },
    { id: 3, admin: 'demo@demo.example', action: 'menu_updated', detail: 'Cambió la foto de un plato', createdAt: iso(24, 0) },
  ];
  return { settings, menu, reservations, messages, activity, seq: 100 };
}

let db;
function load() {
  if (db) return db;
  try {
    db = JSON.parse(store.get(STORE_KEY));
  } catch {
    db = null;
  }
  if (!db || !db.settings) db = seed();
  if (!db.activity) db.activity = [];
  return db;
}
const save = () => store.set(STORE_KEY, JSON.stringify(db));
const newId = (p) => `${p}${++load().seq}`;
const log = (action, detail) => {
  const a = load().activity;
  a.unshift({ id: newId('a'), admin: 'demo@demo.example', action, detail, createdAt: new Date().toISOString() });
  a.length = Math.min(a.length, 200);
};
const IMG_PREFIX = 'data:image/jpeg;base64,';

// ---------- Utilidades de respuesta ----------
const json = (status, body) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });
const ok = (data, message, status = 200) => json(status, { ok: true, data, message });
const fail = (status, message) => json(status, { ok: false, error: { message, details: [{ message }] } });
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const clean = (v) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();

const ACTIVE = ['pending', 'confirmed'];
const rules = () => ({ ...RULES, ...load().settings });
const nowLocal = () => time.nowInTimezone(load().settings.timezone);

function availability(date, partySize) {
  const existing = load()
    .reservations.filter((r) => r.date === date && ACTIVE.includes(r.status))
    .map((r) => ({ timeMinutes: time.toMinutes(r.time), partySize: r.partySize }));
  return slots.computeAvailability({ date, partySize, existing, now: nowLocal(), config: rules() });
}

// ---------- Rutas públicas ----------
function publicRoutes(method, path, query, body) {
  const s = load().settings;
  if (method === 'GET' && path === '/settings/public') {
    const { businessName, timezone, phone, email, address, instagram, whatsapp, maxPartySize, maxDaysAhead, hours } = s;
    return ok({ businessName, timezone, phone, email, address, instagram, whatsapp, maxPartySize, maxDaysAhead, hours });
  }
  if (method === 'GET' && path === '/menu') {
    return ok(load().menu.filter((m) => m.isVisible).sort((a, b) => a.position - b.position).map(({ id, name, description, tag, price, image }) => ({ id, name, description, tag, price, image: image || null })));
  }
  if (method === 'GET' && path === '/reservations/availability') {
    const date = query.get('date');
    const partySize = Number(query.get('partySize') || 1);
    if (!time.isValidDateString(date)) return fail(400, 'Fecha no válida');
    return ok({ date, partySize, slots: availability(date, partySize).map(({ time: t, available }) => ({ time: t, available })) });
  }
  if (method === 'POST' && path === '/reservations') {
    const d = { name: clean(body.name), email: clean(body.email).toLowerCase(), phone: clean(body.phone), partySize: Number(body.partySize), date: body.date, time: body.time, notes: clean(body.notes).slice(0, 500) };
    if (d.name.length < 2) return fail(400, 'El nombre es demasiado corto');
    if (d.email && !EMAIL.test(d.email)) return fail(400, 'Email no válido');
    if (!/^\+?[\d\s()-]{7,20}$/.test(d.phone)) return fail(400, 'Teléfono no válido');
    if (!Number.isInteger(d.partySize) || d.partySize < 1) return fail(400, 'Número de personas no válido');
    if (d.partySize > s.maxPartySize) return fail(422, `Máximo ${s.maxPartySize} personas por reserva. Para grupos más grandes, contáctanos.`);
    if (!time.isValidDateString(d.date)) return fail(400, 'Fecha no válida');
    const slot = availability(d.date, d.partySize).find((x) => x.time === d.time);
    if (!slot) return fail(422, 'Ese horario no está disponible para la fecha elegida. Revisa los horarios de apertura.');
    if (!slot.available) return fail(409, 'Lo sentimos, ese horario ya no está disponible. Elige otro, por favor.');
    const status = s.autoConfirm ? 'confirmed' : 'pending';
    const stamp = new Date().toISOString();
    load().reservations.push({ id: newId('r'), ...d, status, createdAt: stamp, updatedAt: stamp });
    save();
    return ok(
      { status, name: d.name, date: d.date, time: d.time, partySize: d.partySize },
      status === 'confirmed'
        ? d.email ? '¡Reserva confirmada! (En el producto real, aquí se envía un email con los detalles.)' : '¡Reserva confirmada! Te esperamos.'
        : d.email ? 'Recibimos tu solicitud. (En el producto real, te confirmamos por email.)' : 'Recibimos tu solicitud. Te confirmaremos muy pronto por WhatsApp o por teléfono.',
      201
    );
  }
  if (method === 'POST' && path === '/contact') {
    const m = { name: clean(body.name) || 'Anónimo', email: clean(body.email).toLowerCase(), subject: clean(body.subject).slice(0, 120), message: clean(body.message) };
    if (m.email && !EMAIL.test(m.email)) return fail(400, 'Email no válido');
    if (m.message.length < 3) return fail(400, 'El mensaje es demasiado corto');
    load().messages.push({ id: newId('c'), ...m, isRead: false, createdAt: new Date().toISOString() });
    save();
    return ok(null, '¡Gracias! Recibimos tu sugerencia.', 201);
  }
  return null;
}

// ---------- Rutas del panel ----------
const page = (items, query) => {
  const limit = Math.min(100, Math.max(1, Number(query.get('limit')) || 20));
  const p = Math.max(1, Number(query.get('page')) || 1);
  return { items: items.slice((p - 1) * limit, p * limit), page: p, limit, total: items.length };
};

function adminRoutes(method, path, query, body) {
  if (method === 'POST' && path === '/login') {
    if (!clean(body.email) || !clean(body.password)) return fail(400, 'Escribe un email y una contraseña (en el demo sirve cualquiera).');
    store.set(SESSION_KEY, '1', 'session');
    log('login', 'Inició sesión');
    return ok({ admin: { id: 'demo', email: clean(body.email), name: 'Demo' }, csrfToken: 'demo' });
  }
  if (method === 'POST' && path === '/logout') {
    store.del(SESSION_KEY, 'session');
    return ok(null);
  }
  if (!store.get(SESSION_KEY, 'session')) return fail(401, 'Debes iniciar sesión');
  const d = load();

  if (path === '/me') return ok({ admin: { id: 'demo', email: 'demo@demo.example', name: 'Demo' }, csrfToken: 'demo' });

  if (method === 'GET' && path === '/reservations') {
    const st = query.get('status');
    const date = query.get('date');
    const items = d.reservations
      .filter((r) => (!st || r.status === st) && (!date || r.date === date))
      .sort((a, b) => (a.date + a.time < b.date + b.time ? 1 : -1));
    return ok(page(items, query));
  }
  let m = path.match(/^\/reservations\/([^/]+)\/status$/);
  if (m && method === 'PATCH') {
    const r = d.reservations.find((x) => x.id === m[1]);
    if (!r) return fail(404, 'Reserva no encontrada');
    if (r.status === 'cancelled' && body.status !== 'cancelled') return fail(409, 'No se puede reactivar una reserva cancelada. Crea una nueva.');
    r.status = body.status;
    r.updatedAt = new Date().toISOString();
    log('reservation_status', `${r.name} · ${r.date} ${r.time} → ${r.status}`);
    save();
    return ok(r);
  }

  if (method === 'GET' && path === '/messages') {
    const items = d.messages.filter((x) => query.get('unread') !== 'true' || !x.isRead).sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));
    return ok(page(items, query));
  }
  m = path.match(/^\/messages\/([^/]+)(\/read)?$/);
  if (m) {
    const msg = d.messages.find((x) => x.id === m[1]);
    if (!msg) return fail(404, 'Mensaje no encontrado');
    if (method === 'PATCH' && m[2]) msg.isRead = true;
    else if (method === 'DELETE') d.messages = d.messages.filter((x) => x !== msg);
    else return null;
    save();
    return ok(msg);
  }

  if (path === '/settings' && method === 'GET') return ok(d.settings);
  if (path === '/settings' && method === 'PUT') {
    if (clean(body.businessName).length < 2) return fail(400, 'El nombre del negocio es demasiado corto');
    try {
      new Intl.DateTimeFormat('en-CA', { timeZone: body.timezone });
    } catch {
      return fail(400, 'Zona horaria no válida');
    }
    for (const day of Object.values(body.hours || {})) if (day && day[0] >= day[1]) return fail(400, 'La hora de cierre debe ser posterior a la de apertura');
    const digits = (v) => String(v ?? '').replace(/\D/g, '');
    const changed = Object.keys(body).filter((k) => JSON.stringify(body[k]) !== JSON.stringify(d.settings[k]));
    d.settings = { ...d.settings, ...body, whatsapp: digits(body.whatsapp), countryCode: digits(body.countryCode) };
    log('settings_updated', changed.length ? `Cambió: ${changed.join(', ')}` : 'Sin cambios');
    save();
    return ok(d.settings);
  }

  if (method === 'GET' && path === '/activity') return ok(page(d.activity, query));

  if (path === '/menu' && method === 'GET') return ok([...d.menu].sort((a, b) => a.position - b.position));
  if (path === '/menu' && method === 'POST') {
    if (!clean(body.name)) return fail(400, 'El nombre del plato es demasiado corto');
    if (d.menu.length >= 60) return fail(409, 'El menú admite hasta 60 platos.');
    const item = { id: newId('m'), name: clean(body.name), description: clean(body.description), tag: clean(body.tag), price: clean(body.price), position: Math.max(0, ...d.menu.map((x) => x.position)) + 1, isVisible: !!body.isVisible, image: null };
    d.menu.push(item);
    log('menu_created', item.name);
    save();
    return ok(item, undefined, 201);
  }
  m = path.match(/^\/menu\/([^/]+)\/image$/);
  if (m) {
    const item = d.menu.find((x) => x.id === m[1]);
    if (!item) return fail(404, 'Plato no encontrado');
    if (method === 'PUT') {
      if (!/^[A-Za-z0-9+/]+=*$/.test(body.image || '')) return fail(400, 'La imagen no es válida.');
      item.image = IMG_PREFIX + body.image;
      log('menu_updated', 'Cambió la foto de un plato');
    } else if (method === 'DELETE') {
      item.image = null;
      log('menu_updated', 'Quitó la foto de un plato');
    } else return null;
    save();
    return ok(null);
  }
  m = path.match(/^\/menu\/([^/]+)(\/move)?$/);
  if (m) {
    const item = d.menu.find((x) => x.id === m[1]);
    if (!item) return fail(404, 'Plato no encontrado');
    if (method === 'PUT') {
      if (!clean(body.name)) return fail(400, 'El nombre del plato es demasiado corto');
      Object.assign(item, { name: clean(body.name), description: clean(body.description), tag: clean(body.tag), price: clean(body.price), isVisible: !!body.isVisible });
    } else if (method === 'DELETE') {
      d.menu = d.menu.filter((x) => x !== item);
    } else if (method === 'PATCH' && m[2]) {
      const sorted = [...d.menu].sort((a, b) => a.position - b.position);
      const i = sorted.indexOf(item);
      const j = body.direction === 'up' ? i - 1 : i + 1;
      if (j >= 0 && j < sorted.length) [sorted[i], sorted[j]] = [sorted[j], sorted[i]];
      sorted.forEach((x, k) => (x.position = k + 1));
    } else return null;
    save();
    return ok(item);
  }
  return null;
}

// ---------- Intercepta fetch hacia /api/... ----------
const realFetch = window.fetch.bind(window);
window.fetch = async (input, init = {}) => {
  const raw = typeof input === 'string' ? input : input.url;
  const match = String(raw).match(/\/api\/([^?#]*)(?:\?([^#]*))?/);
  if (!match) return realFetch(input, init);

  const method = (init.method || (typeof input !== 'string' && input.method) || 'GET').toUpperCase();
  let body = {};
  try {
    body = init.body ? JSON.parse(init.body) : {};
  } catch {
    body = {};
  }
  const query = new URLSearchParams(match[2] || '');
  const full = '/' + match[1].replace(/\/$/, '');
  await new Promise((r) => setTimeout(r, 120)); // pequeña pausa para que se sienta como una red real
  try {
    const res = full.startsWith('/admin') ? adminRoutes(method, full.slice(6) || '/', query, body) : publicRoutes(method, full, query, body);
    return res || fail(404, 'Ruta no encontrada');
  } catch (err) {
    return fail(500, 'Error en el demo: ' + err.message);
  }
};

